def _add_bom(path: Path) -> None:
    path.write_bytes(b"\xef\xbb\xbf" + path.read_bytes())


def _k_trap_mix(root: Path) -> None:
    """Byte-order marks, references and carriers keyed in other letter cases and with spaces, board numbers with
    spaces, re-keyed loads, decimal minimums."""
    rng = random.Random(1717)

    def respell(rows):
        for r in rows:
            if rng.random() < 0.06:
                ref = r["customer_ref"].strip()
                r["customer_ref"] = rng.choice([ref.lower(), " " + ref, ref + "  ", " " + ref.lower()])
        return rows
    _edit_rows(root / "orders.csv", respell)

    def rekey(rows):
        out = []
        fleet = sorted({r["carrier"] for r in rows})
        for i, r in enumerate(rows):
            if i % 37 == 5:
                out.append(dict(r, quantity=f"{Decimal(r['quantity'].strip()) * Decimal('1.13'):.3f}", carrier=rng.choice(fleet)))
            if i % 41 == 7:  # a void first keying at another depot, a week off
                elsewhere = rng.choice(sorted({x["depot"] for x in rows} - {r["depot"]}))
                out.append(dict(r, depot=elsewhere, arrived_at=_iso(_ts(r["arrived_at"]) - 7 * 86400 + 3600, -6)))
            out.append(r)
            if i % 53 == 11:
                out.append(dict(r))
        for r in out:
            if rng.random() < 0.08:
                name = r["carrier"].strip()
                r["carrier"] = rng.choice([name.upper(), name.lower(), " " + name, name + " "])
        return out
    _edit_rows(root / "receipts.csv", rekey)

    def pad_board(rows):
        for r in rows:
            if r["status"] == "VOID-DUP" and rng.random() < 0.5:
                r["po_number"] = rng.choice([" ", "  "]) + r["po_number"].strip() + rng.choice(["", " "])
        return rows
    _edit_rows(root / "dispatch_board_final.csv", pad_board)

    def minimums(rows):
        for r in rows:
            if r["segment"] == "public" and r["contract_min_t"] not in ("0", "") and rng.random() < 0.3:
                r["contract_min_t"] = f"{int(Decimal(r['contract_min_t']))}.{rng.randint(1, 9)}"
        return rows
    _edit_rows(root / "contracts.csv", minimums)
    for name in ("receipts.csv", "orders.csv", "contracts.csv"):
        _add_bom(root / name)


def _k_late_versions(root: Path) -> None:
    """No version before the first allocation (standing defaults, null version id), a replace and a patch at one
    instant (version id order), CRM rows tied at one instant written in Z and in -06:00."""
    start, ends = _season_bounds(root)

    def change(doc):
        doc["versions"] = [
            {"version_id": "LV-02", "effective_at": _iso(ends[3] + 3600, -6), "mode": "patch",
             "values": {"review_floor": "0.98", "tie_break": "oldest_open_lot", "allocation_unit_kg": 5000}},
            {"version_id": "LV-01", "effective_at": _iso(ends[3] + 3600, 0), "mode": "replace",
             "values": {"public_weight": 3, "bonus_composition": "multiplicative", "review_round_limit": 2}},
            {"version_id": "LV-03", "effective_at": _iso(ends[11] - 600, -5), "mode": "patch",
             "values": {"review_floor": "0.93", "deficit_threshold": "0.57"}},
        ]
    _edit_json(root / "allocation_parameters.json", change)
    plain = _plain_customers(root)

    def crm(doc):
        rows = doc["accounts"]
        for i, c in enumerate(plain[:12]):
            mine = [r for r in rows if r["customer_id"] == c]
            if not mine:
                continue
            top = max(int(r["revision"]) for r in mine)
            t = (ends[2 + i] + ends[3 + i]) // 2
            rows.append(dict(mine[0], route_source="crm", critical_route=True, revision=top + 1, updated_at=_iso(t, 0)))
            rows.append(dict(mine[0], route_source="crm", critical_route=False, revision=top + 2, updated_at=_iso(t, -6)))
        doc["accounts"] = rows
    _edit_json(root / "crm_accounts.json", crm)


def _k_quiet_regions(root: Path) -> None:
    """Two regions never short and no public customer in any rationed allocation."""
    depots = {d.get("code"): d.get("region") for d in ET.parse(root / "depots.xml").getroot().findall("depot")}
    rich = sorted(d for d, r in depots.items() if r in ("North", "West"))

    def receipts(rows):
        for r in rows:
            if depots[r["depot"]] in ("North", "West"):
                r["quantity"] = f"{Decimal(r['quantity'].strip()) * 4:.3f}"
            else:
                r["quantity"] = f"{Decimal(r['quantity'].strip()) * Decimal('0.6'):.3f}"
        return rows
    _edit_rows(root / "receipts.csv", receipts)
    seg = {r["customer_id"]: r["segment"] for r in _rows(root / "contracts.csv")}

    def areas(doc):
        for i, a in enumerate(doc["assignments"]):
            if seg.get(a["customer_id"]) == "public":
                a["depot"] = rich[i % len(rich)]
    _edit_json(root / "service_areas.json", areas)


