def _corpus(name: str) -> Path:
    def build():
        root = _private_dir(f"3f39299a-20c7-5792-a6e6-b2a616a3ec30-{name}-") / "extract"
        if name in _FRESH:
            root.mkdir()
        else:
            shutil.copytree(_shipped_dir(), root)
            _reweigh(root, 5000 + int(name[1:]) * 37, _FLEET[name])
        _BUILDERS[name](root)
        _apply_witness(root, _WITNESS_PLAN.get(name, []))
        _assert_distinct(root)
        _finish(root, 9100 + int(name[1:]) * 53)
        return root
    return _memo(("corpus", name), build)


